// src/components/Navbar.jsx
import React from 'react';
import { Link } from 'react-router-dom';

const Navbar = () => {
  return (
    <nav className="bg-studentDark p-4 shadow-md">
      <div className="container mx-auto flex justify-between items-center">
        <Link to="/" className="text-white text-2xl font-bold">
           My opportunities
        </Link>
        <div className="space-x-4">
          <Link to="/" className="text-gray-300 hover:text-white transition duration-200">
            Home
          </Link>
          <Link to="/opportunities" className="text-gray-300 hover:text-white transition duration-200">
            Opportunities
          </Link>
          <Link to="/auth" className="text-gray-300 hover:text-white transition duration-200">
           Login / Registration
           </Link>
            <Link to="/profile" className="text-gray-300 hover:text-white transition duration-200">
            Profile
          </Link>
          <Link to="/myapplication"style={{textDecoration:'none',color:'#4a3f6b',}} lassName="text-gray-300 hover:text-white transition duration-200">
           MyApplications
           </Link>
          
          
          
          
          {/* رابط خاص بصفحة الطلاب */}
          <Link to="/student-dashboard" className="text-studentAccent hover:text-white transition duration-200 font-semibold">
            student control panel
          </Link>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;
